package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.BeanPropertyMap;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.util.NameTransformer;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.HashSet;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

/**
 * Unit tests for BeanDeserializer.deserializeFromNull.
 * Since the method is protected, we use a Test subclass to expose it.
 */
public class BeanDeserializer_deserializeFromNull_TriageGen1Test {

    private TestBeanDeserializer deserializer;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private BeanDescription mockBeanDesc;

    // Subclass to access protected method and manipulate protected fields
    private static class TestBeanDeserializer extends BeanDeserializer {
        private boolean vanillaProcessingOverride = false;

        protected TestBeanDeserializer(BeanDeserializerBuilder builder, BeanDescription beanDesc, 
                                      BeanPropertyMap properties, java.util.Map<String, SettableBeanProperty> backRefs, 
                                      HashSet<String> ignorableProps, boolean ignoreAllUnknown, boolean hasViews) {
            super(builder, beanDesc, properties, backRefs, ignorableProps, ignoreAllUnknown, hasViews);
        }

        public void setVanillaProcessing(boolean vanilla) {
            this.vanillaProcessingOverride = vanilla;
        }

        @Override
        protected boolean isVanillaProcessing() {
            return vanillaProcessingOverride;
        }

        @Override
        protected Object vanillaDeserialize(JsonParser p, DeserializationContext ctxt, JsonToken t) throws IOException {
            return "vanilla_result";
        }

        @Override
        protected Object deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException {
            return "object_result";
        }

        @Override
        protected Class<?> handledType() {
            return Object.class;
        }

        // Expose the protected method for testing
        @Override
        public Object deserializeFromNull(JsonParser p, DeserializationContext ctxt) throws IOException {
            return super.deserializeFromNull(p, ctxt);
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockBeanDesc = mock(BeanDescription.class);

        // Minimal setup for BeanDeserializerBuilder via constructor requirements
        BeanDeserializerBuilder builder = mock(BeanDeserializerBuilder.class);
        deserializer = new TestBeanDeserializer(
                builder, 
                mockBeanDesc, 
                BeanPropertyMap.builder(mockBeanDesc).build(), 
                Collections.emptyMap(), 
                new HashSet<>(), 
                true, 
                false
        );
    }

    @Test
    public void testDeserializeFromNull_WhenRequiresCustomCodecIsFalse() throws IOException {
        // Arrange
        when(mockParser.requiresCustomCodec()).thenReturn(false);
        Object expectedException = new JsonMappingException(mockParser, "Unexpected token");
        when(mockContext.handleUnexpectedToken(any(), eq(mockParser))).thenReturn(expectedException);

        // Act
        Object result = deserializer.deserializeFromNull(mockParser, mockContext);

        // Assert
        assertSame(expectedException, result);
        verify(mockContext).handleUnexpectedToken(eq(Object.class), eq(mockParser));
    }

    @Test
    public void testDeserializeFromNull_WhenRequiresCustomCodecIsTrue_AndVanillaProcessingIsTrue() throws IOException {
        // Arrange
        when(mockParser.requiresCustomCodec()).thenReturn(true);
        deserializer.setVanillaProcessing(true);

        // Act
        Object result = deserializer.deserializeFromNull(mockParser, mockContext);

        // Assert
        assertEquals("vanilla_result", result);
    }

    @Test
    public void testDeserializeFromNull_WhenRequiresCustomCodecIsTrue_AndVanillaProcessingIsFalse() throws IOException {
        // Arrange
        when(mockParser.requiresCustomCodec()).thenReturn(true);
        deserializer.setVanillaProcessing(false);

        // Act
        Object result = deserializer.deserializeFromNull(mockParser, mockContext);

        // Assert
        assertEquals("object_result", result);
    }
}
